select #{push} time,a.app_name name,t.link_sum num
from (select app_type,max(link_num) link_sum
       from TRAFFIC_APP_STATISTIC
       where stat_time>= #{start}
          and stat_time<#{end}
          group by app_type) t , ui_code_app_dic a
 where t.app_type=a.view_code
 order by num desc
 limit 10;


select #{push} time,service type,sum(sum) num
from NTC_SERVICE_REPORT
where report_time>= #{start}
and report_time< #{end}
group by type;


	SELECT sum(MONITOR_NUM) as visitsNum,sum(REJECT_NUM)  as controlNum,sum(REPLACE_NUM) as replaceNum
        FROM pxy_total_report
        WHERE REPORT_TIME >= #{start}
       AND REPORT_TIME < #{end}


SELECT #{push} time,ACCOUNT account,NAS_IP nas_ip,sum(num) num
FROM ntc_radius_report
WHERE report_time >= #{start}
    AND report_time < #{end}
    GROUP BY account ,nas_ip
    ORDER BY num DESC
     LIMIT 100;


